package com.lexiscan.auth; import com.lexiscan.auth.AuthDtos.*; import com.lexiscan.common.ApiException; import com.lexiscan.user.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { final UserRepository users; final PasswordEncoder encoder; final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthResponse register(RegisterRequest r){if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new ApiException(HttpStatus.CONFLICT,"Email already registered");var u=new User();u.setName(r.name().trim());u.setEmail(r.email().trim().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));users.save(u);return response(u);} public AuthResponse login(LoginRequest r){var u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!u.isEnabled())throw new ApiException(HttpStatus.FORBIDDEN,"Account is disabled");if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);} public AuthResponse response(User u){return new AuthResponse(jwt.issue(u),view(u));} public UserResponse view(User u){return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole(),u.isEnabled());} }
